class Solution {
public:
    int stoneGameVI(vector<int>& aliceValues, vector<int>& bobValues) {
        int n = aliceValues.size();
        // Sum range is [2, 200] since each value is in [1, 100]
        vector<vector<int>> buckets(201);
        for (int i = 0; i < n; i++) {
            int s = aliceValues[i] + bobValues[i];
            buckets[s].push_back(i);
        }
        long long aliceScore = 0, bobScore = 0;
        bool aliceTurn = true;
        for (int s = 200; s >= 2; s--) {
            for (int idx : buckets[s]) {
                if (aliceTurn) {
                    aliceScore += aliceValues[idx];
                } else {
                    bobScore += bobValues[idx];
                }
                aliceTurn = !aliceTurn;
            }
        }
        if (aliceScore > bobScore) return 1;
        if (aliceScore < bobScore) return -1;
        return 0;
    }
};
